# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student

def make_student(last, first):
    return Student("id-" + last, last, first, "A")

PEOPLE = [
    make_student("Halloway", "Juno"),
    make_student("Dunmere", "Piet"),
    make_student("Avery", "Kit")
]

class SeatRowsTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        self.assertEqual(
            seat_rows(PEOPLE, 2),
            [
                "Row 1: Avery, Kit | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_single_row_when_seats_exceed_students(self):
        lines = seat_rows(PEOPLE, 10)
        self.assertEqual(len(lines), 1)
        self.assertTrue(lines[0].startswith("Row 1: Avery"))

    def test_ties_break_on_first_name(self):
        pair = [make_student("Lane", "Zed"),
                make_student("Lane", "Abe")]
        self.assertEqual(
            seat_rows(pair, 2),
            ["Row 1: Lane, Abe | Lane, Zed"]
        )

    def test_sort_ignores_case(self):
        pair = [make_student("beck", "Al"),
                make_student("Adams", "Bo")]
        self.assertTrue(
            seat_rows(pair, 1)[0].startswith("Row 1: Adams")
        )

    def test_input_is_not_modified(self):
        before = list(PEOPLE)
        seat_rows(PEOPLE, 2)
        self.assertEqual(PEOPLE, before)

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(PEOPLE, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(PEOPLE, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
